def _ensure_dict(data):
    """Normalize BSD YAML data (list or dict) to dict keyed by ID"""
    if isinstance(data, list):
        result = {}
        for item in data:
            key = item.get("_id")
            if key is not None:
                result[key] = item
        return result
    return data or {}

