def check_sde_extended() -> int:
    """返回新表就绪数量 (0-3): category=1, station=1, region=1"""
    ready = 0
    try:
        with sqlite3.connect(REF_DB_PATH) as conn:
            c = conn.cursor()
            c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='category'")
            if c.fetchone():
                c.execute("SELECT COUNT(*) FROM category")
                if int(c.fetchone()[0]) > 0:
                    ready += 1
            c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='station'")
            if c.fetchone():
                c.execute("SELECT COUNT(*) FROM station")
                if int(c.fetchone()[0]) > 0:
                    ready += 1
            c.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='region'")
            if c.fetchone():
                c.execute("SELECT COUNT(*) FROM region")
                if int(c.fetchone()[0]) > 0:
                    ready += 1
    except Exception:
        pass
    return ready

